Translate the following MS C++ code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original MS C++ code you have to translate:
<original_code>
#include <iostream>
#include <cmath>
using namespace std;

long long get_gcd(int a, int b) {
    while (b != 0) {
        int temp = a % b;
        a = b;
        b = temp;
    }
    return a;
}

long long get_lcm(int a, int b) {
    return (long long)a * b / get_gcd(a, b);
}

double get_diff(int x1, int y1, int x2, int y2) {
    long long l = get_lcm(y1, y2);
    long long diff = abs(l / y1 * x1 - l / y2 * x2);
    return (double)diff / l;
}

int main() {
    int x, y, n;
    cin >> x >> y >> n;
    double min_ratio_diff = 1e20;
    int best_b = 1;
    double base_ratio = (double)x / y;

    for (int i = 1; i <= n; ++i) {
        int low = 1, high = 1000000;
        while (high - low > 1) {
            int mid = (low + high) / 2;
            double ratio = (double)mid / i;
            if (ratio < base_ratio)
                low = mid;
            else
                high = mid;
        }
        int candidate = low;
        double diff_left = get_diff(candidate, i, x, y);
        double diff_right = get_diff(high, i, x, y);
        int chosen = (diff_left < diff_right) ? candidate : high;
        double current_diff = get_diff(chosen, i, x, y);
        if (current_diff < min_ratio_diff) {
            min_ratio_diff = current_diff;
            best_b = i;
        }
    }
    cout << best_b << "/" << n;
    return 0;
}
